8	export function keyOf(d: Date): DayKey {
9	  const m = `${d.getMonth() + 1}`.padStart(2, '0');
10	  const day = `${d.getDate()}`.padStart(2, '0');
11	  return `${d.getFullYear()}-${m}-${day}`;
12	}
